from django.core.exceptions import PermissionDenied
from django.shortcuts import get_object_or_404

def invoice_detail(request, pk):
    invoice = get_object_or_404(
        Invoice.objects.select_related("customer"),
        pk=pk,
        tenant=request.tenant,
    )
    if not request.user.has_perm("billing.view_invoice", invoice):
        raise PermissionDenied
    return render(request, "billing/detail.html", {"invoice": invoice})

# Requires an S3-compatible storage backend such as django-storages.
from storages.backends.s3 import S3Storage

storage = S3Storage()

def download_invoice(request, invoice_id):
    invoice = get_object_or_404(Invoice, pk=invoice_id, tenant=request.tenant)
    url = storage.url(
        invoice.file.name,
        expire=300,
        parameters={
            "ResponseContentDisposition": f'attachment; filename="{invoice.safe_filename}"'
        },
    )
    return redirect(url)

import hashlib
import hmac

def provider_webhook(request):
    signature = request.headers.get("X-Provider-Signature", "")
    expected = hmac.new(
        settings.PROVIDER_WEBHOOK_SECRET.encode(),
        request.body,
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return HttpResponse(status=401)

    payload = json.loads(request.body)
    with transaction.atomic():
        event, created = WebhookEvent.objects.get_or_create(
            provider="provider",
            event_id=payload["id"],
            defaults={"event_type": payload["type"]},
        )
        if not created:
            return HttpResponse(status=200)
        apply_event(payload)  # idempotent state transition
    return HttpResponse(status=200)

from django.core.cache import cache

def login_view(request):
    key = f"login-attempts:{client_ip(request)}"
    attempts = cache.get(key, 0)
    if attempts >= 5:
        return HttpResponse("Too many attempts. Try again later.", status=429)

    # On failure:
    cache.set(key, attempts + 1, timeout=15 * 60)
    # On success:
    cache.delete(key)

